from datetime import datetime
for value in ['0001-01-01T00:00:00Z', '9999-12-31T23:59:59Z']:
    value_dt = datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ')
    try:
        print(value, value_dt.timestamp())
    except Exception as error:
        print(value, type(error).__name__, error)
